import CoreAILanguageModels
import Foundation

struct Batch: Decodable {
    let name: String
    let model: String
    let vocabSize: Int
    let candidateIDs: [Int]
    let cases: [TestCase]
}

struct TestCase: Decodable {
    let id: String
    let suite: String
    let ids: [Int32]
    let tokenizationMS: Double
}

struct Result: Encodable {
    let id: String
    let suite: String
    let tokenCount: Int
    let scores: [Float]
    let greedyToken: Int32
    let inferenceMS: Double
    let tokenizationMS: Double
    let cachedPrefixTokens: Int
}

struct RunError: Error {
    let message: String
}

func milliseconds(_ duration: Duration) -> Double {
    let parts = duration.components
    return Double(parts.seconds) * 1_000 + Double(parts.attoseconds) / 1e15
}

@main
struct Evaluate {
    static func main() async {
        do {
            try await run()
        } catch {
            FileHandle.standardError.write(Data("Error: \(String(reflecting: error))\n".utf8))
            exit(1)
        }
    }

    static func run() async throws {
        let args = CommandLine.arguments
        let batch = try JSONDecoder().decode(Batch.self, from: Data(contentsOf: URL(fileURLWithPath: args[1])))
        let mode = args.count > 2 ? args[2] : "coreai-sequential"
        let limit = args.count > 3 ? Int(args[3]) ?? batch.cases.count : batch.cases.count
        let modelURL = URL(fileURLWithPath: batch.model, isDirectory: true)
        let config = ModelConfig(
            name: batch.name, tokenizer: "local", vocabSize: batch.vocabSize,
            maxContextLength: 1024, serializedModel: [modelURL.lastPathComponent], function: "main"
        )
        let clock = ContinuousClock()
        let started = clock.now
        let engine = try await EngineFactory.createEngine(
            config: JSONEncoder().encode(config), modelURL: modelURL,
            options: EngineOptions(variant: mode, kvCacheSize: 1024)
        )
        print("{\"loadMS\":\(milliseconds(started.duration(to: clock.now))),\"mode\":\"\(mode)\"}")
        fflush(stdout)
        let warmups = Array(batch.cases.prefix(3))
        var sharedCount = 0
        if ProcessInfo.processInfo.environment["MH_DUPLEX_CACHE_PREFIX"] == "1" {
            let ids = batch.cases[0].ids
            sharedCount = ids.indices.first { i in batch.cases.contains { row in i >= row.ids.count || row.ids[i] != ids[i] } } ?? (ids.count - 1)
            if sharedCount > 0 {
                let prefix = try await engine.generate(
                    with: Array(ids.prefix(sharedCount)), samplingConfiguration: .greedy,
                    inferenceOptions: InferenceOptions(maxTokens: 1, includeLogits: false)
                )
                for try await _ in prefix {}
                guard engine.processedTokenCount == sharedCount else { throw RunError(message: "Unexpected prefix state count") }
                try await engine.checkpoint()
            }
        }
        var rejectedSuites = Set<String>()
        for (index, row) in (warmups + Array(batch.cases.prefix(limit))).enumerated() {
            if rejectedSuites.contains(row.suite) { continue }
            let start = clock.now
            try await engine.reset(to: sharedCount)
            let stream = try await engine.generate(
                with: row.ids, samplingConfiguration: .greedy,
                inferenceOptions: InferenceOptions(maxTokens: 1, includeLogits: engine.supportsLogits)
            )
            var result: Result?
            for try await step in stream {
                let scores = step.logits.map { logits in batch.candidateIDs.map { Float(logits[$0]) } } ?? []
                guard scores.allSatisfy(\.isFinite) else { throw RunError(message: "Nonfinite logits for \(row.id)") }
                result = Result(
                    id: row.id, suite: row.suite, tokenCount: row.ids.count, scores: scores,
                    greedyToken: step.tokenId, inferenceMS: milliseconds(start.duration(to: clock.now)),
                    tokenizationMS: row.tokenizationMS, cachedPrefixTokens: engine.lastPrefixHitCount
                )
            }
            guard let result else { throw RunError(message: "No result for \(row.id)") }
            if index >= warmups.count {
                print(String(decoding: try JSONEncoder().encode(result), as: UTF8.self))
                fflush(stdout)
                if result.inferenceMS + result.tokenizationMS > 100 {
                    rejectedSuites.insert(row.suite)
                }
            }
        }
    }
}
